tool_input.command:
cat > /tmp/new_head.scss <<'EOF'
// Theme Colors (blue marketplace tokens; flat, no gradients)
$user-primary-400: $blue-600;
$user-primary-500: $blue-600;
$user-primary-600: $blue-700;

$user-secondary-400: $blue-600;
$user-secondary-500: $blue-600;
$user-secondary-600: $blue-700;

$user-accent-400: $ok;
$user-accent-500: $ok;
$user-accent-600: $ok;

// Background Colors
$user-bg-base: $page;
$user-bg-surface: $surface;
$user-bg-elevated: $blue-50;
$user-bg-hover: $blue-50;

// Border Colors
$user-border-subtle: $line;
$user-border-default: $line;
$user-border-strong: #C9D2DE;

// Text Colors
$user-text-primary: $ink;
$user-text-secondary: $ink-2;
$user-text-muted: $ink-2;

// Gradient variables are flat aliases
$user-gradient-primary: $blue-600;
$user-gradient-accent: $blue-600;
EOF
f=src/styles/themes/_user.scss; { head -8 $f; cat /tmp/new_head.scss; tail -n +41 $f; } > /tmp/user_new.scss && cp /tmp/user_new.scss $f && sed -n 1,12p $f && sed -n 36,42p $f
